-- Skema PEJADIN untuk PostgreSQL / Supabase (dijalankan otomatis oleh backend saat tabel belum ada)
create table users(id bigserial primary key,username text unique not null,password_hash text not null,nama text,pegawai_id bigint,role text not null,aktif int not null default 1,last_login timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table pegawai(id bigserial primary key,nama text not null,nip text unique not null,golongan text,pangkat text,jabatan text,eselon text,tingkat_biaya text,unit_kerja text,aktif int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table tarif(id bigserial primary key,tahun int not null,provinsi text not null,harian bigint,inap1 bigint,inap2 bigint,inap3 bigint,inap4 bigint,taksi bigint,uang_harian_dalam_kota_8jam bigint not null default 0,uang_harian_diklat bigint not null default 0,unique(tahun,provinsi),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table uang_representasi(tahun int not null,kategori text not null,luar_kota_oh bigint not null,dalam_kota_8jam bigint not null,primary key(tahun,kategori));
create table golongan_pangkat(golongan text primary key,nama_pangkat text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table pejabat(id bigserial primary key,peran text,nama text,nip text,jabatan text,aktif int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table dasar_hukum(id bigserial primary key,urutan int,teks text,aktif int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table satker(k text primary key,v text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table satker_tahunan(tahun_anggaran int primary key,nama_kementerian varchar(150),nama_ditjen varchar(150),nama_satker varchar(200),nama_satker_panjang varchar(250),alamat text,kode_satker varchar(10),nomor_dipa varchar(100),tanggal_dipa date,dipa_raw text,klasifikasi_anggaran varchar(100),kode_akun_belanja varchar(10),rekening_bendahara varchar(100),nomor_sptjb varchar(100),akun_default varchar(50),kota varchar(50),kota_kedudukan varchar(50),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table st(id bigserial primary key,nomor text,tahun int,maksud text,nama_kegiatan text,asal text,provinsi_asal text,tujuan text,provinsi text,tgl_berangkat date,tgl_kembali date,tgl_tiba date,tanggal_surat_tugas date,tgl_tanda_tangan date,nomor_bukti text,uraian_kegiatan text,keterangan_laporan text,alat text,akun text,jenis text,status text not null default 'DRAFT',alasan text,dibuat_oleh text,diterbitkan_oleh text,diterbitkan_pada timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table spd(id bigserial primary key,st_id bigint not null references st(id) on delete cascade,urutan int,pegawai_id bigint references pegawai(id),nama text,nip text,golongan text,pangkat text,tingkat_biaya text,jabatan text,eselon text,hari int,malam int,tarif_inap bigint,tiket bigint,lain bigint,biaya_riil bigint,ppn bigint,pph bigint,tarif_harian bigint,uang_harian bigint,uang_inap bigint,taksi bigint,tarif_rep bigint,rep bigint,jumlah bigint,batas bigint,flag int,tgl_tiba_pengesahan date,status text not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table audit(id bigserial primary key,pengguna text,aksi text,entitas text,eid bigint,detail text,waktu timestamptz default now());
create table audit_log(id bigserial primary key,user_id bigint,aksi text,entitas text,entitas_id bigint,detail jsonb,ip_address text,created_at timestamptz not null default now());
create table notifications(id bigserial primary key,user_id bigint not null references users(id) on delete cascade,st_id bigint not null references st(id) on delete cascade,action text not null,title text not null,message text not null,created_at timestamptz not null default now(),read_at timestamptz);
create index ix_notifications_user_unread on notifications(user_id,read_at,created_at desc);
create table dokumen_terbit(id bigserial primary key,surat_tugas_id bigint references st(id),spd_id bigint references spd(id),jenis_dokumen text,storage_key text,dicetak_oleh bigint,dicetak_pada timestamptz not null default now());
create unique index ux_nomor on st(tahun,nomor) where nomor is not null;
create index ix_spd_st on spd(st_id);
create index ix_st_status on st(status);
-- Keamanan Supabase: matikan akses lewat Data API (anon/authenticated). Backend memakai role postgres yang melewati RLS.
alter table users enable row level security;alter table pegawai enable row level security;alter table tarif enable row level security;alter table uang_representasi enable row level security;alter table golongan_pangkat enable row level security;alter table pejabat enable row level security;
alter table dasar_hukum enable row level security;alter table satker enable row level security;alter table satker_tahunan enable row level security;alter table st enable row level security;alter table spd enable row level security;alter table audit enable row level security;alter table audit_log enable row level security;alter table notifications enable row level security;alter table dokumen_terbit enable row level security;
